// ---------- webstore_create ----------

void test_webstore_create_has_three_tables(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_PTR_NOT_NULL(store.merch_ht);
	CU_ASSERT_PTR_NOT_NULL(store.cart_ht);
	CU_ASSERT_PTR_NOT_NULL(store.storage_ht);

	ioopm_webstore_destroy(&store);
}

void test_webstore_create_tables_are_separate(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_PTR_NOT_EQUAL(store.merch_ht, store.cart_ht);
	CU_ASSERT_PTR_NOT_EQUAL(store.merch_ht, store.storage_ht);
	CU_ASSERT_PTR_NOT_EQUAL(store.cart_ht, store.storage_ht);

	ioopm_webstore_destroy(&store);
}

void test_webstore_create_tables_are_empty(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.merch_ht));
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.cart_ht));
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.storage_ht));

	ioopm_webstore_destroy(&store);
}

void test_webstore_create_first_cart_number_is_one(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_EQUAL(store.next_cart_num, 1);

	ioopm_webstore_destroy(&store);
}

void test_webstore_create_string_tables_compare_by_contents(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	char key1[] = "Apple";
	char key2[] = "Apple";
	elem_t found;

	ioopm_hash_table_insert(store.merch_ht, string_elem(key1), int_elem(1));
	ioopm_hash_table_insert(store.storage_ht, string_elem(key1), int_elem(2));

	// A different pointer with the same contents finds the same entry
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.merch_ht, string_elem(key2), &found));
	CU_ASSERT_EQUAL(found.i, 1);
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.storage_ht, string_elem(key2), &found));
	CU_ASSERT_EQUAL(found.i, 2);

	elem_t removed;
	ioopm_hash_table_remove(store.merch_ht, string_elem(key1), &removed);
	ioopm_hash_table_remove(store.storage_ht, string_elem(key1), &removed);
	ioopm_webstore_destroy(&store);
}

void test_webstore_create_cart_table_compares_ints(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	elem_t found;

	ioopm_hash_table_insert(store.cart_ht, int_elem(7), int_elem(70));

	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.cart_ht, int_elem(7), &found));
	CU_ASSERT_EQUAL(found.i, 70);
	CU_ASSERT_FALSE(ioopm_hash_table_has_key(store.cart_ht, int_elem(8)));

	elem_t removed;
	ioopm_hash_table_remove(store.cart_ht, int_elem(7), &removed);
	ioopm_webstore_destroy(&store);
}

void test_webstore_create_twice_gives_separate_stores(void)
{
	ioopm_webstore_t store1 = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_webstore_t store2 = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_PTR_NOT_EQUAL(store1.merch_ht, store2.merch_ht);
	CU_ASSERT_PTR_NOT_EQUAL(store1.cart_ht, store2.cart_ht);
	CU_ASSERT_PTR_NOT_EQUAL(store1.storage_ht, store2.storage_ht);

	// Adding to one store doesn't change the other
	ioopm_cart_add_new(&store1, string_hash, string_eq);
	CU_ASSERT_EQUAL(store1.next_cart_num, 2);
	CU_ASSERT_EQUAL(store2.next_cart_num, 1);
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store2.cart_ht));

	ioopm_cart_destroy(&store1, 1);
	ioopm_webstore_destroy(&store1);
	ioopm_webstore_destroy(&store2);
}

// ---------- webstore_destroy ----------

void test_webstore_destroy_empty_store(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	// Passes if it doesn't crash (and with no leaks under valgrind, see make memtest)
	ioopm_webstore_destroy(&store);
}

void test_webstore_destroy_after_destroy_all(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);

	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, make_merch("Apple", "Red fruit", 10)));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_replenish(&store, "Apple", "A01", 5));
	int cart_num = ioopm_cart_add_new(&store, string_hash, string_eq);
	CU_ASSERT_TRUE_FATAL(ioopm_cart_add_item(&store, cart_num, "Apple", 2));

	// This is how the program shuts down: free the contents, then the store
	ioopm_merch_destroy_all(&store);
	ioopm_cart_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

void test_webstore_destroy_after_removing_contents(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	elem_t removed;

	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, make_merch("Apple", "Red fruit", 10)));
	int cart_num = ioopm_cart_add_new(&store, string_hash, string_eq);

	// Remove everything one by one instead
	CU_ASSERT_TRUE_FATAL(ioopm_cart_destroy(&store, cart_num));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_remove(&store, "Apple", &removed));
	ioopm_merch_destroy(removed.p);

	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.merch_ht));
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.cart_ht));
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(store.storage_ht));

	ioopm_webstore_destroy(&store);
}


